427	                .max(constraints.min.width)
428	                + self.gap,
429	        )?;
430	        let index = self
431	            .focus
432	            .and_then(|w| self.column_index(w))
433	            .map_or(self.columns.len(), |i| i + 1);
434	        let group = GroupId(self.next_group);
435	        self.next_group = self
