440	        self.columns.insert(
441	            index,
442	            Column {
443	                group,
444	                windows: vec![window],
445	                width: self.default_width,
446	                mode: ColumnMode::Stack,
447	                active: window,
448	                scroll_y: 0.0,
449	            },
450	        );
451	        // Seed only the new canvas member. Existing canvas positions survive strip operations.
452	        let strip = self.strip_placements();
