        None
    };
    let c = &mut self.columns[index];
    c.windows.retain(|w| *w != window);
    if c.windows.is_empty() {
        self.canvas.remove(&c.group);
        self.columns.remove(index);
    } else if c.active == window {
        c.active = c
            .windows
            .iter()
            .copied()
            .find(|w| !self.minimized.contains(w))
