pub fn focus_direction(
    &mut self,
    direction: Direction,
) -> Result<Option<WindowId>, LayoutError> {
    let Some(window) = self.focus else {
        return Ok(None);
    };
    let next = if self.mode == LayoutMode::Strip && self.fullscreen.is_empty() {
        let i = self.column_index(window).unwrap();
        let c = &self.columns[i];
        let j = c.windows.iter().position(|w| *w == window).unwrap();
        match direction {
            Direction::Left => self.columns[..i]
                .iter()
                .rev()
                .map(|c| c.active)
                .find(|w| !self.is_minimized(*w)),
            Direction::Right => self.columns[i + 1..]
                .iter()
                .map(|c| c.active)
                .find(|w| !self.is_minimized(*w)),
            Direction::Up => c.windows[..j]
                .iter()
                .rev()
                .copied()
                .find(|w| !self.is_minimized(*w)),
            Direction::Down => c.windows[j + 1..]
                .iter()
                .copied()
                .find(|w| !self.is_minimized(*w)),
        }
    } else {
        let placements = self.projected_placements();
        let source = placements.iter().find(|p| p.window == window).unwrap().rect;
        let origin = center(source);
        placements
            .iter()
            .filter(|p| p.window != window && p.visible)
            .filter_map(|candidate| {
                let r = candidate.rect;
                let p = center(r);
                let (forward, perpendicular, edge) = match direction {
                    Direction::Left => (
                        origin.x - p.x,
                        (origin.y - p.y).abs(),
                        source.x - (r.x + r.width),
                    ),
                    Direction::Right => (
                        p.x - origin.x,
                        (origin.y - p.y).abs(),
                        r.x - (source.x + source.width),
                    ),
                    Direction::Up => (
                        origin.y - p.y,
                        (origin.x - p.x).abs(),
                        source.y - (r.y + r.height),
                    ),
                    Direction::Down => (
                        p.y - origin.y,
                        (origin.x - p.x).abs(),
                        r.y - (source.y + source.height),
                    ),
                };
                (forward > 0.0).then_some((
                    candidate.window,
                    perpendicular / forward,
                    edge.max(0.0),
                    perpendicular,
                ))
            })
            .min_by(|a, b| {
                a.1.total_cmp(&b.1)
                    .then(a.2.total_cmp(&b.2))
                    .then(a.3.total_cmp(&b.3))
                    .then(a.0.cmp(&b.0))
            })
