1	//! One virtual-output composition's geometry and copied surface input regions.
2	use crate::Fluxwm;
3	use flux_core::{Point as ModelPoint, Rect, WindowId};
4	use flux_scene::{SceneInput, SceneSnapshot, round_rect_to_i32};
5	use smithay::{
6	    backend::renderer::{
7	        RendererSuper,
8	        element::{
9	            Element, Id, Kind, RenderElement, render_elements,
10	            solid::{SolidColorBuffer, SolidColorRenderElement},
11	            surface::WaylandSurfaceRenderElement,
12	            utils::CropRenderElement,
13	        },
14	        gles::GlesRenderer,
15	        utils::{CommitCounter, DamageSet, RendererSurfaceStateUserData},
16	    },
17	    desktop::PopupManager,
18	    reexports::wayland_server::protocol::wl_surface::WlSurface,
19	    utils::{
20	        Buffer, IsAlive, Logical, Physical, Point, Rectangle, Scale, Transform,
21	        user_data::UserDataMap,
22	    },
23	    wayland::compositor::{
24	        RegionAttributes, SurfaceAttributes, TraversalAction, get_parent, with_states,
25	        with_surface_tree_downward,
26	    },
27	};
28	
29	const MAX_SURFACES: usize = 16_384;
30	const MAX_REGION_RECTS: usize = 65_536;
31	const MAX_TREE_DEPTH: usize = 128;
32	
33	struct Tree {
34	    window: WindowId,
35	    popup: bool,
36	    fullscreen: bool,
37	    surface: WlSurface,
38	    origin: Point<i32, Logical>,
39	    clip: Rectangle<i32, Logical>,
40	}
41	struct InputSurface {
42	    window: WindowId,
43	    tree_root: WlSurface,
44	    popup: bool,
45	    fullscreen: bool,
46	    surface: WlSurface,
47	    origin: Point<f64, Logical>,
48	    bounds: Rectangle<f64, Logical>,
49	    clip: Rectangle<f64, Logical>,
50	    region: Option<RegionAttributes>,
51	}
52	
53	render_elements! {
54	    pub SceneRenderElement<=GlesRenderer>;
55	    Surface=CropRenderElement<WaylandSurfaceRenderElement<GlesRenderer>>,
56	    FullscreenSurface=FullscreenSurfaceRenderElement,
57	    Backdrop=SolidColorRenderElement,
58	}
59	
60	// Client opaque-region claims are optimization hints, not evidence that ARGB
61	// pixels are opaque. Fullscreen must always compose its trusted black page
62	// beneath every client pixel, including popups and subsurfaces. This wrapper
63	// keeps the surface's actual alpha and draw behavior while exposing no opaque
64	// regions or direct-scanout storage to the composition machinery.
65	pub struct FullscreenSurfaceRenderElement(
66	    CropRenderElement<WaylandSurfaceRenderElement<GlesRenderer>>,
67	);
68	
69	impl Element for FullscreenSurfaceRenderElement {
70	    fn id(&self) -> &Id {
71	        self.0.id()
72	    }
73	    fn current_commit(&self) -> CommitCounter {
74	        self.0.current_commit()
75	    }
76	    fn src(&self) -> Rectangle<f64, Buffer> {
77	        self.0.src()
78	    }
79	    fn transform(&self) -> Transform {
80	        self.0.transform()
81	    }
82	    fn geometry(&self, scale: Scale<f64>) -> Rectangle<i32, Physical> {
83	        self.0.geometry(scale)
84	    }
85	    fn damage_since(
86	        &self,
87	        scale: Scale<f64>,
88	        commit: Option<CommitCounter>,
89	    ) -> DamageSet<i32, Physical> {
90	        self.0.damage_since(scale, commit)
91	    }
92	    fn alpha(&self) -> f32 {
93	        self.0.alpha()
94	    }
95	    fn kind(&self) -> Kind {
96	        self.0.kind()
97	    }
98	    // Element::opaque_regions defaults to empty; do not delegate client claims.
99	}
100	
101	impl RenderElement<GlesRenderer> for FullscreenSurfaceRenderElement {
102	    fn draw(
103	        &self,
104	        frame: &mut <GlesRenderer as RendererSuper>::Frame<'_, '_>,
105	        src: Rectangle<f64, Buffer>,
106	        dst: Rectangle<i32, Physical>,
107	        damage: &[Rectangle<i32, Physical>],
108	        _opaque_regions: &[Rectangle<i32, Physical>],
109	        cache: Option<&UserDataMap>,
110	    ) -> Result<(), <GlesRenderer as RendererSuper>::Error> {
111	        self.0.draw(frame, src, dst, damage, &[], cache)
112	    }
113	}
114	
115	enum Layer {
116	    Surface(usize),
117	    Backdrop {
118	        clip: Rectangle<i32, Logical>,
119	        element: SolidColorRenderElement,
120	    },
121	}
122	
123	pub struct RuntimeScene {
124	    geometry: SceneSnapshot,
125	    // Both lists are front to back, matching Smithay's element ordering.
126	    input: Vec<InputSurface>,
127	    layers: Vec<Layer>,
128	    popup_surfaces: usize,
129	}
130	
131	impl RuntimeScene {
132	    pub fn surface_counts(&self) -> (usize, usize) {
133	        (self.input.len(), self.popup_surfaces)
134	    }
135	    pub fn capture(state: &Fluxwm, viewport: Rect) -> Result<Self, String> {
136	        let placements = state.layout.placements();
137	        let mut inputs = Vec::new();
138	        let mut owners = Vec::new();
139	        for (z, window) in state.space.elements().enumerate() {
140	            let Some(top) = window.toplevel() else {
141	                continue;
142	            };
143	            let Some(id) = state.window_id(top.wl_surface()) else {
144	                continue;
145	            };
146	            if !state.windows.get(id).is_some_and(|item| item.mapped) {
147	                continue;
148	            }
149	            let Some(placement) = placements.iter().find(|p| p.window == id && p.visible) else {
150	                continue;
151	            };
152	            let Some(location) = state.space.element_location(window) else {
153	                continue;
154	            };
155	            let geo = window.geometry();
156	            let bbox = window.bbox();
157	            let size = bbox.size;
158	            let origin = checked_sub(location, geo.loc)?;
159	            let visual_origin = checked_add(origin, bbox.loc)?;
160	            let clip = state.layout.camera().rect_to_view(placement.clip);
161	            let fullscreen = state.layout.is_fullscreen(id);
162	            let fullscreen_clip = if fullscreen {
163	                clipped_page(clip, viewport)?
164	            } else {
165	                None
166	            };
167	            if fullscreen && fullscreen_clip.is_none() {
168	                continue;
169	            }
170	            if owners.len() >= MAX_SURFACES {
171	                return Err("scene owner budget exceeded".into());
172	            }
173	            owners.push((id, window.clone(), location, origin, fullscreen_clip));
174	            if size.w <= 0 || size.h <= 0 {
175	                continue;
176	            }
177	            let visual = Rect {
178	                x: f64::from(visual_origin.x),
179	                y: f64::from(visual_origin.y),
180	                width: f64::from(size.w),
181	                height: f64::from(size.h),
182	            };
183	            let Some(mut input) = clipped_root_input(id, visual, clip, viewport)? else {
184	                continue;
185	            };
186	            input.z_index = z as i32;
187	            input.focused = placement.focused;
188	            inputs.push(input);
189	        }
190	        let geometry = SceneSnapshot::new(viewport, inputs).map_err(|e| e.to_string())?;
191	        let viewport = rectangle(viewport)?;
192	        let mut input = Vec::new();
193	        let mut layers = Vec::new();
194	        let mut region_rects = 0;
195	        let visited = std::cell::Cell::new(0);
196	        let mut tree_count = 0;
197	        for (id, window, location, origin, fullscreen_clip) in owners.into_iter().rev() {
198	            let mut trees = Vec::new();
199	            let Some(top) = window.toplevel() else {
200	                continue;
201	            };
202	            // Popup eligibility follows mapped scene ownership, independently
203	            // of whether the root's own buffer intersects its container/output.
204	            for (popup, offset) in PopupManager::popups_for_surface(top.wl_surface()) {
205	                let offset = checked_sub(offset, popup.geometry().loc)?;
206	                let popup_origin = checked_add(location, offset)?;
207	                if tree_count >= MAX_SURFACES {
208	                    return Err("scene tree budget exceeded".into());
209	                }
210	                tree_count += 1;
211	                trees.push(Tree {
212	                    window: id,
213	                    popup: true,
214	                    fullscreen: fullscreen_clip.is_some(),
215	                    surface: popup.wl_surface().clone(),
216	                    origin: popup_origin,
217	                    clip: fullscreen_clip.unwrap_or(viewport),
218	                });
219	            }
220	            if let Some(entry) = geometry.entries().iter().find(|entry| entry.window() == id) {
221	                if tree_count >= MAX_SURFACES {
222	                    return Err("scene tree budget exceeded".into());
223	                }
224	                tree_count += 1;
225	                trees.push(Tree {
226	                    window: id,
227	                    popup: false,
228	                    fullscreen: fullscreen_clip.is_some(),
229	                    surface: top.wl_surface().clone(),
230	                    origin,
231	                    clip: rectangle(entry.effective_clip())?,
232	                });
233	            }
234	            for tree in &trees {
235	                let first = input.len();
236	                capture_input(tree, &mut input, &mut region_rects, &visited)?;
237	                layers.extend((first..input.len()).map(Layer::Surface));
238	            }
239	            // Fullscreen belongs to this frozen owner group: popups and the
240	            // whole client tree draw above it; every lower owner draws below.
241	            // Keep it even when the centered client lies outside the viewport.
242	            if let Some(clip) = fullscreen_clip {
243	                let buffer = SolidColorBuffer::new(clip.size, [0.0, 0.0, 0.0, 1.0]);
244	                let element = SolidColorRenderElement::from_buffer(
245	                    &buffer,
246	                    clip.loc.to_physical(1),
247	                    1.0,
248	                    1.0,
249	                    Kind::Unspecified,
250	                );
251	                layers.push(Layer::Backdrop { clip, element });
252	            }
253	        }
254	        let popup_surfaces = input.iter().filter(|surface| surface.popup).count();
255	        Ok(Self {
256	            geometry,
257	            input,
258	            layers,
259	            popup_surfaces,
260	        })
261	    }
262	
263	    pub fn windows(&self) -> impl Iterator<Item = WindowId> + '_ {
264	        self.input
265	            .iter()
266	            .filter(|node| {
267	                let bounds = Rectangle::new(node.origin, node.bounds.size);
268	                bounds.overlaps(node.clip)
269	            })
270	            .map(|node| node.window)
271	            .collect::<std::collections::BTreeSet<_>>()
272	            .into_iter()
273	    }
274	
275	    pub fn render_elements(
276	        &self,
277	        renderer: &mut GlesRenderer,
278	    ) -> Result<Vec<SceneRenderElement>, String> {
279	        let mut elements = Vec::new();
280	        for layer in &self.layers {
281	            let node = match layer {
282	                Layer::Surface(index) => &self.input[*index],
283	                Layer::Backdrop { element, .. } => {
284	                    elements.push(SceneRenderElement::Backdrop(element.clone()));
285	                    continue;
286	                }
287	            };
288	            // Propagate import failures rather than publishing input eligibility
289	            // for a surface silently omitted by the convenience tree helper.
290	            let element = with_states(&node.surface, |states| {
291	                WaylandSurfaceRenderElement::from_surface(
292	                    renderer,
293	                    &node.surface,
294	                    states,
295	                    node.origin.to_physical(1.0),
296	                    1.0,
297	                    Kind::Unspecified,
298	                )
299	            })
300	            .map_err(|error| format!("scene surface import failed: {error}"))?
301	            .ok_or("mapped scene surface produced no render element")?;
302	            if let Some(element) = CropRenderElement::from_element(
303	                element,
304	                1.0,
305	                node.clip
306	                    .to_i32_round::<i32>()
307	                    .to_physical_precise_round(1.0),
308	            ) {
309	                elements.push(if node.fullscreen {
310	                    SceneRenderElement::FullscreenSurface(FullscreenSurfaceRenderElement(element))
311	                } else {
312	                    SceneRenderElement::Surface(element)
313	                });
314	            }
315	        }
316	        Ok(elements)
317	    }
318	
319	    pub fn hit(
320	        &self,
321	        pos: Point<f64, Logical>,
322	        state: &Fluxwm,
323	    ) -> Option<(WindowId, WlSurface, Point<f64, Logical>)> {
324	        if !pos.x.is_finite()
325	            || !pos.y.is_finite()
326	            || !self
327	                .geometry
328	                .viewport()
329	                .contains(ModelPoint { x: pos.x, y: pos.y })
330	        {
331	            return None;
332	        }
333	        for layer in &self.layers {
334	            let node = match layer {
335	                Layer::Surface(index) => &self.input[*index],
336	                Layer::Backdrop { clip, .. } => {
337	                    // The black pixels belong to this presented scene even if
338	                    // their old owner has since disappeared. Block click-through
339	                    // until a replacement frame removes the page.
340	                    if clip.to_f64().contains(pos) {
341	                        return None;
342	                    }
343	                    continue;
344	                }
345	            };
346	            if !owner_eligible(state, node.window)
347	                || !node.surface.alive()
348	                || !node.clip.contains(pos)
349	            {
350	                continue;
351	            }
352	            if node.popup {
353	                let Some(top) = state
354	                    .windows
355	                    .get(node.window)
356	                    .and_then(|item| item.window.toplevel())
357	                else {
358	                    continue;
359	                };
360	                if !PopupManager::popups_for_surface(top.wl_surface())
361	                    .any(|(popup, _)| popup.wl_surface() == &node.tree_root)
362	                {
363	                    continue;
364	                }
365	            }
366	            if !still_mapped_in_tree(&node.surface, &node.tree_root) {
367	                continue;
368	            }
369	            let local = pos - node.origin;
370	            if !node.bounds.contains(local)
371	                || node
372	                    .region
373	                    .as_ref()
374	                    .is_some_and(|r| !r.contains(local.to_i32_floor()))
375	            {
376	                continue;
377	            }
378	            return Some((node.window, node.surface.clone(), node.origin));
379	        }
380	        None
381	    }
382	}
383	
384	fn owner_eligible(state: &Fluxwm, window: WindowId) -> bool {
385	    !state.layout.is_minimized(window)
386	        && state.windows.get(window).is_some_and(|item| {
387	            item.mapped
388	                && item
389	                    .window
390	                    .toplevel()
391	                    .is_some_and(|top| still_mapped_in_tree(top.wl_surface(), top.wl_surface()))
392	        })
393	}
394	
395	// Intersect floating-point world projections before conversion, then use the
396	// same rounded rectangle for opaque pixels, popup clipping, and input blocking.
397	fn clipped_page(page: Rect, viewport: Rect) -> Result<Option<Rectangle<i32, Logical>>, String> {
398	    let Some(clip) = flux_scene::intersection(page, viewport).map_err(|error| error.to_string())?
399	    else {
400	        return Ok(None);
401	    };
402	    Ok(round_rect_to_i32(clip)
403	        .map_err(|error| error.to_string())?
404	        .map(|rect| Rectangle::new((rect.x, rect.y).into(), (rect.width, rect.height).into())))
405	}
406	
407	fn checked_sub(
408	    a: Point<i32, Logical>,
409	    b: Point<i32, Logical>,
410	) -> Result<Point<i32, Logical>, String> {
411	    Ok((
412	        a.x.checked_sub(b.x).ok_or("scene origin overflow")?,
413	        a.y.checked_sub(b.y).ok_or("scene origin overflow")?,
414	    )
415	        .into())
416	}
417	fn checked_add(
418	    a: Point<i32, Logical>,
419	    b: Point<i32, Logical>,
420	) -> Result<Point<i32, Logical>, String> {
421	    Ok((
422	        a.x.checked_add(b.x).ok_or("scene origin overflow")?,
423	        a.y.checked_add(b.y).ok_or("scene origin overflow")?,
424	    )
425	        .into())
426	}
427	fn rectangle(rect: Rect) -> Result<Rectangle<i32, Logical>, String> {
428	    let value = round_rect_to_i32(rect)
429	        .map_err(|e| e.to_string())?
430	        .ok_or("scene clip collapsed")?;
431	    Ok(Rectangle::new(
432	        (value.x, value.y).into(),
433	        (value.width, value.height).into(),
434	    ))
435	}
436	
437	fn capture_input(
438	    tree: &Tree,
439	    nodes: &mut Vec<InputSurface>,
440	    region_rects: &mut usize,
441	    visited: &std::cell::Cell<usize>,
442	) -> Result<(), String> {
443	    let overflow = std::cell::Cell::new(false);
444	    with_surface_tree_downward(
445	        &tree.surface,
446	        (tree.origin.to_f64(), 0usize),
447	        |_, states, (origin, depth)| {
448	            if overflow.get() {
449	                return TraversalAction::SkipChildren;
450	            }
451	            if *depth >= MAX_TREE_DEPTH || visited.get() >= MAX_SURFACES {
452	                overflow.set(true);
453	                return TraversalAction::SkipChildren;
454	            }
455	            visited.set(visited.get() + 1);
456	            let view = states
457	                .data_map
458	                .get::<RendererSurfaceStateUserData>()
459	                .and_then(|d| d.lock().unwrap().view());
460	            match view {
461	                Some(view) => {
462	                    TraversalAction::DoChildren((*origin + view.offset.to_f64(), depth + 1))
463	                }
464	                None => TraversalAction::SkipChildren,
465	            }
466	        },
467	        |surface, states, (origin, _)| {
468	            if overflow.get() {
469	                return;
470	            }
471	            let Some(view) = states
472	                .data_map
473	                .get::<RendererSurfaceStateUserData>()
474	                .and_then(|d| d.lock().unwrap().view())
475	            else {
476	                return;
477	            };
478	            let mut attributes = states.cached_state.get::<SurfaceAttributes>();
479	            let region = &attributes.current().input_region;
480	            let count = region.as_ref().map_or(0, |r| r.rects.len());
481	            if nodes.len() >= MAX_SURFACES || count > MAX_REGION_RECTS - *region_rects {
482	                overflow.set(true);
483	                return;
484	            }
485	            *region_rects += count;
486	            nodes.push(InputSurface {
487	                window: tree.window,
488	                tree_root: tree.surface.clone(),
489	                popup: tree.popup,
490	                fullscreen: tree.fullscreen,
491	                surface: surface.clone(),
492	                origin: *origin + view.offset.to_f64(),
493	                bounds: Rectangle::from_size(view.dst).to_f64(),
494	                clip: tree.clip.to_f64(),
495	                region: region.clone(),
496	            });
497	        },
498	        |_, _, _| !overflow.get(),
499	    );
500	    if overflow.get() {
501	        Err("scene surface/input-region budget exceeded".into())
502	    } else {
503	        Ok(())
504	    }
505	}
506	
507	// Protocol lifecycle invalidates eligibility immediately, even while the last
508	// composed geometry remains on screen. Do not recompute geometry/input regions.
509	fn still_mapped_in_tree(surface: &WlSurface, anchor: &WlSurface) -> bool {
510	    let mut current = surface.clone();
511	    for _ in 0..MAX_TREE_DEPTH {
512	        if !current.alive() {
513	            return false;
514	        }
515	        let mapped = with_states(&current, |states| {
516	            states
517	                .data_map
518	                .get::<RendererSurfaceStateUserData>()
519	                .is_some_and(|data| data.lock().unwrap().view().is_some())
520	        });

