614	    fn constraints_for(&self, surface: &WlSurface) -> SizeConstraints {
615	        smithay::wayland::compositor::with_states(surface, |states| {
616	            let mut cached = states.cached_state.get::<SurfaceCachedState>();
617	            let data = cached.current();
618	            SizeConstraints::from_xdg(
619	                (data.min_size.w, data.min_size.h),
620	                (data.max_size.w, data.max_size.h),
621	            )
622	            .unwrap_or_default()
623	        })
624	    }
