626	    pub fn relayout(&mut self) {
627	        // Capacity depends on the other members and viewport, not just the
628	        // rejected client's hints. Retry retained buffers on model changes so
629	        // a static client does not need to commit again after capacity returns.
630	        // One arena-order pass (at most the 1,024 owned roles), no timer or
631	        // recursive relayout. Recovery preserves the current selection.
632	        let pending: Vec<_> = self
633	            .windows
634	            .iter()
635	            .filter_map(|(id, item)| {
636	                (item.buffered
637	                    && !item.mapped
638	                    && item.admission_error.is_some()
639	                    && item.window.alive())
640	                .then_some(id)
641	            })
642	            .collect();
643	        let mut admitted = false;
644	        for id in pending {
645	            let surface = self
646	                .windows
647	                .get(id)
648	                .and_then(|item| item.window.toplevel())
649	                .expect("live rejected role in one dispatch")
650	                .wl_surface()
651	                .clone();
652	            if self
653	                .layout
654	                .insert_with_focus(id, self.constraints_for(&surface), false)
655	                .is_ok()
656	            {
657	                if self.apply_initial_states(id).is_err() {
658	                    let _ = self.layout.remove(id);
659	                    continue;
660	                }
661	                let item = self.windows.get_mut(id).expect("live dispatch ID");
662	                item.mapped = true;
663	                item.admission_error = None;
664	                self.stats.maps += 1;
665	                self.bump_sequence();
666	                admitted = true;
667	                tracing::info!(%id, "window_admission_recovered");
668	            }
669	        }
670	        for placement in self.layout.placements() {
671	            let Some(item) = self.windows.get(placement.window) else {
672	                continue;
673	            };
674	            if !item.mapped {
675	                continue;
676	            }
677	            if let Some(toplevel) = item.window.toplevel() {
678	                toplevel.with_pending_state(|s| {
679	                    s.size = Some((placement.rect.width.round() as i32, placement.rect.height.round() as i32).into());
680	                    if self.layout.is_fullscreen(placement.window) {
681	                        s.states.set(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Fullscreen);
682	                    } else {
683	                        s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Fullscreen);
684	                    }
685	                    if self.layout.is_maximized(placement.window) && !self.layout.is_fullscreen(placement.window) {
686	                        s.states.set(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Maximized);
687	                    } else {
688	                        s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Maximized);
689	                    }
690	                    if self.layout.is_minimized(placement.window) {
691	                        s.states.set(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Suspended);
692	                    } else {
693	                        s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Suspended);
694	                    }
695	                    if placement.focused { s.states.set(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Activated); }
696	                    else { s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Activated); }
697	                });
698	                crate::configure::send_pending(toplevel);
699	            }
700	            if placement.visible {
701	                let mut rect = self.layout.camera().rect_to_view(placement.rect);
702	                if self.layout.is_fullscreen(placement.window) {
703	                    let size = item.window.geometry().size;
704	                    rect.x += (rect.width - f64::from(size.w)).max(0.0) / 2.0;
705	                    rect.y += (rect.height - f64::from(size.h)).max(0.0) / 2.0;
706	                }
707	                self.space.map_element(
708	                    item.window.clone(),
709	                    (rect.x.round() as i32, rect.y.round() as i32),
710	                    placement.focused,
711	                );
712	            } else {
713	                if let Some(toplevel) = item.window.toplevel() {
714	                    Self::dismiss_root_popups(toplevel.wl_surface());
715	                }
716	                self.space.unmap_elem(&item.window);
717	            }
718	        }
719	        // map_element raises even inactive elements. Restore focus stacking after
720	        // mapping every placement, including background maximized overlays.
721	        if let Some(item) = self.layout.focused().and_then(|id| self.windows.get(id))
722	            && self.space.element_location(&item.window).is_some()
723	        {
724	            self.space.raise_element(&item.window, false);
725	        }
726	        // Release seat wrappers only after all scene removals are authoritative;
727	        // cleanup repairs keyboard/pointer focus using the completed layout.
728	        self.cleanup_popup_grab();
729	        if admitted {
730	            self.restore_keyboard_focus();
731	        }
732	        self.request_redraw();
733	    }
