735	    fn reject_invalid_configured_size(&self, top: &smithay::wayland::shell::xdg::ToplevelSurface) {
736	        use smithay::reexports::{
737	            wayland_protocols::xdg::shell::server::xdg_wm_base, wayland_server::Resource,
738	        };
739	        let Some(client) = top.wl_surface().client() else {
740	            return;
741	        };
742	        let mut resource = None;
743	        // The public ShellClient hides its wm_base resource. Find a live typed
744	        // wm_base owned by this same client. Never query the backend under its
745	        // object-enumeration lock. A protocol error terminates this client only.
746	        let _ = self
747	            .display_handle
748	            .backend_handle()
749	            .with_all_objects_for(client.id(), |id| {
750	                if resource.is_none()
751	                    && id.interface().name == xdg_wm_base::XdgWmBase::interface().name
752	                {
753	                    resource = Some(id);
754	                }
755	            });
756	        if let Some(resource) =
757	            resource.and_then(|id| xdg_wm_base::XdgWmBase::from_id(&self.display_handle, id).ok())
758	        {
759	            resource.post_error(
760	                xdg_wm_base::Error::InvalidSurfaceState,
761	                "committed window geometry violates acknowledged fullscreen or maximized configure",
762	            );
763	        } else {
764	            self.display_handle
765	                .backend_handle()
766	                .kill_client(client.id(), DisconnectReason::ConnectionClosed);
767	        }
768	    }
