770	    fn apply_initial_states(&mut self, id: WindowId) -> Result<(), flux_layout::LayoutError> {
771	        let requested = self
772	            .windows
773	            .get(id)
774	            .expect("admitted role")
775	            .initial_maximized;
776	        let max_result = match self.layout.set_maximized(id, requested) {
777	            Err(
778	                flux_layout::LayoutError::InvalidConstraints
779	                | flux_layout::LayoutError::InvalidGeometry,
780	            ) => {
781	                // Hints or viewport may change between the initial configure and
782	                // first buffer. Keep successful base admission and send normal
783	                // state rather than trapping the live client in a retry loop.
784	                self.windows
785	                    .get_mut(id)
786	                    .expect("admitted role")
787	                    .initial_maximized = false;
788	                self.bump_sequence();
789	                self.layout.set_maximized(id, false)
790	            }
791	            result => result,
792	        };
793	        max_result?;
794	        let requested = self
795	            .windows
796	            .get(id)
797	            .expect("admitted role")
798	            .initial_fullscreen;
799	        match self.layout.set_fullscreen(id, requested) {
800	            Err(
801	                flux_layout::LayoutError::InvalidConstraints
802	                | flux_layout::LayoutError::InvalidGeometry,
803	            ) => {
804	                self.windows
805	                    .get_mut(id)
806	                    .expect("admitted role")
807	                    .initial_fullscreen = false;
808	                self.bump_sequence();
809	                self.layout.set_fullscreen(id, false)
810	            }
811	            result => result,
812	        }
813	    }
