815	    fn owns_click_grab(&self, id: WindowId) -> bool {
816	        use smithay::reexports::wayland_server::Resource;
817	        let Some(top) = self.windows.get(id).and_then(|item| item.window.toplevel()) else {
818	            return false;
819	        };
820	        let Some(pointer) = self.seat.get_pointer() else {
821	            return false;
822	        };
823	        pointer
824	            .with_grab(|_, grab| grab.is::<smithay::input::pointer::ClickGrab<Self>>())
825	            .unwrap_or(false)
826	            && pointer
827	                .grab_start_data()
828	                .and_then(|data| data.focus)
829	                .is_some_and(|(focus, _)| focus.id().same_client_as(&top.wl_surface().id()))
830	    }
