832	    pub fn set_window_maximized(&mut self, id: WindowId, maximized: bool) -> Result<(), String> {
833	        if self.stopping || self.shutdown_deadline.is_some() {
834	            return Err("instance is shutting down".into());
835	        }
836	        let item = self
837	            .windows
838	            .get(id)
839	            .filter(|item| item.window.alive())
840	            .ok_or("unknown window")?;
841	        let current = if item.mapped {
842	            self.layout.is_maximized(id)
843	        } else {
844	            item.initial_maximized
845	        };
846	        if current == maximized {
847	            return Ok(());
848	        }
849	        if self.seat.get_keyboard().is_some_and(|k| k.is_grabbed())
850	            || (self.seat.get_pointer().is_some_and(|p| p.is_grabbed())
851	                && !self.owns_click_grab(id))
852	        {
853	            return Err("an input grab is active".into());
854	        }
855	        if item.mapped {
856	            self.layout
857	                .set_maximized(id, maximized)
858	                .map_err(|e| e.to_string())?;
859	            self.relayout();
860	        } else {
861	            let size =
862	                if maximized {
863	                    self.layout
864	                        .maximize_size(self.constraints_for(
865	                            item.window.toplevel().expect("xdg role").wl_surface(),
866	                        ))
867	                        .map_err(|e| e.to_string())?
868	                } else {
869	                    self.layout.viewport()
870	                };
871	            let item = self.windows.get_mut(id).expect("live role");
872	            item.initial_maximized = maximized;
873	            if let Some(top) = item.window.toplevel() {
874	                if item.initial_fullscreen {
875	                    top.with_pending_state(|s|s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Maximized));
876	                } else {
877	                    top.with_pending_state(|s| {
878	                    s.size = maximized.then(|| (size.width.round() as i32, size.height.round() as i32).into());
879	                    if maximized { s.states.set(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Maximized); }
880	                    else { s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Maximized); }
881	                });
882	                }
883	            }
884	        }
885	        self.bump_sequence();
886	        Ok(())
887	    }
