891	            return Err("instance is shutting down".into());
892	        }
893	        let item = self
894	            .windows
895	            .get(id)
896	            .filter(|i| i.window.alive())
897	            .ok_or("unknown window")?;
898	        let current = if item.mapped {
899	            self.layout.is_fullscreen(id)
900	        } else {
901	            item.initial_fullscreen
902	        };
903	        if current == fullscreen {
904	            return Ok(());
905	        }
906	        if self.seat.get_keyboard().is_some_and(|k| k.is_grabbed())
907	            || (self.seat.get_pointer().is_some_and(|p| p.is_grabbed())
908	                && !self.owns_click_grab(id))
909	        {
910	            return Err("an input grab is active".into());
911	        }
912	        if item.mapped {
913	            self.layout
914	                .set_fullscreen(id, fullscreen)
915	                .map_err(|e| e.to_string())?;
916	            self.relayout();
917	        } else {
918	            let top = item.window.toplevel().expect("xdg role").clone();
919	            let constraints = self.constraints_for(top.wl_surface());
920	            let size = if fullscreen {
921	                Some(
922	                    self.layout
923	                        .fullscreen_size(constraints)
924	                        .map_err(|e| e.to_string())?,
925	                )
926	            } else if item.initial_maximized {
927	                self.layout.maximize_size(constraints).ok()
928	            } else {
929	                None
930	            };
931	            let item = self.windows.get_mut(id).expect("live role");
932	            item.initial_fullscreen = fullscreen;
933	            if !fullscreen && size.is_none() {
934	                item.initial_maximized = false;
