fn constraints_for(&self, surface: &WlSurface) -> SizeConstraints {
    smithay::wayland::compositor::with_states(surface, |states| {
        let mut cached = states.cached_state.get::<SurfaceCachedState>();
        let data = cached.current();
        SizeConstraints::from_xdg(
            (data.min_size.w, data.min_size.h),
            (data.max_size.w, data.max_size.h),
        )
        .unwrap_or_default()
    })
}

pub fn relayout(&mut self) {
    // Capacity depends on the other members and viewport, not just the
    // rejected client's hints. Retry retained buffers on model changes so
    // a static client does not need to commit again after capacity returns.
    // One arena-order pass (at most the 1,024 owned roles), no timer or
    // recursive relayout. Recovery preserves the current selection.
    let pending: Vec<_> = self
        .windows
        .iter()
        .filter_map(|(id, item)| {
            (item.buffered
                && !item.mapped
                && item.admission_error.is_some()
                && item.window.alive())
            .then_some(id)
        })
        .collect();
    let mut admitted = false;
    for id in pending {
        let surface = self
            .windows
            .get(id)
            .and_then(|item| item.window.toplevel())
            .expect("live rejected role in one dispatch")
            .wl_surface()
            .clone();
        if self
            .layout
            .insert_with_focus(id, self.constraints_for(&surface), false)
            .is_ok()
        {
            if self.apply_initial_states(id).is_err() {
                let _ = self.layout.remove(id);
                continue;
            }
            let item = self.windows.get_mut(id).expect("live dispatch ID");
            item.mapped = true;
            item.admission_error = None;
            self.stats.maps += 1;
            self.bump_sequence();
            admitted = true;
            tracing::info!(%id, "window_admission_recovered");
        }
    }
    for placement in self.layout.placements() {
        let Some(item) = self.windows.get(placement.window) else {
            continue;
        };
        if !item.mapped {
            continue;
        }
        if let Some(toplevel) = item.window.toplevel() {
            toplevel.with_pending_state(|s| {
                s.size = Some((placement.rect.width.round() as i32, placement.rect.height.round() as i32).into());
                if self.layout.is_fullscreen(placement.window) {
                    s.states.set(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Fullscreen);
                } else {
                    s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Fullscreen);
                }
                if self.layout.is_maximized(placement.window) && !self.layout.is_fullscreen(placement.window) {
                    s.states.set(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Maximized);
                } else {
                    s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Maximized);
                }
                if self.layout.is_minimized(placement.window) {
                    s.states.set(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Suspended);
                } else {
                    s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Suspended);
                }
                if placement.focused { s.states.set(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Activated); }
                else { s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Activated); }
            });
            crate::configure::send_pending(toplevel);
        }
        if placement.visible {
            let mut rect = self.layout.camera().rect_to_view(placement.rect);
            if self.layout.is_fullscreen(placement.window) {
                let size = item.window.geometry().size;
                rect.x += (rect.width - f64::from(size.w)).max(0.0) / 2.0;
                rect.y += (rect.height - f64::from(size.h)).max(0.0) / 2.0;
            }
            self.space.map_element(
                item.window.clone(),
                (rect.x.round() as i32, rect.y.round() as i32),
                placement.focused,
            );
        } else {
            if let Some(toplevel) = item.window.toplevel() {
                Self::dismiss_root_popups(toplevel.wl_surface());
            }
            self.space.unmap_elem(&item.window);
        }
    }
    // map_element raises even inactive elements. Restore focus stacking after
    // mapping every placement, including background maximized overlays.
    if let Some(item) = self.layout.focused().and_then(|id| self.windows.get(id))
        && self.space.element_location(&item.window).is_some()
    {
        self.space.raise_element(&item.window, false);
    }
    // Release seat wrappers only after all scene removals are authoritative;
    // cleanup repairs keyboard/pointer focus using the completed layout.
    self.cleanup_popup_grab();
    if admitted {
        self.restore_keyboard_focus();
    }
    self.request_redraw();
}

fn reject_invalid_configured_size(&self, top: &smithay::wayland::shell::xdg::ToplevelSurface) {
    use smithay::reexports::{
        wayland_protocols::xdg::shell::server::xdg_wm_base, wayland_server::Resource,
    };
    let Some(client) = top.wl_surface().client() else {
        return;
    };
    let mut resource = None;
    // The public ShellClient hides its wm_base resource. Find a live typed
    // wm_base owned by this same client. Never query the backend under its
    // object-enumeration lock. A protocol error terminates this client only.
    let _ = self
        .display_handle
        .backend_handle()
        .with_all_objects_for(client.id(), |id| {
            if resource.is_none()
                && id.interface().name == xdg_wm_base::XdgWmBase::interface().name
            {
                resource = Some(id);
            }
        });
    if let Some(resource) =
        resource.and_then(|id| xdg_wm_base::XdgWmBase::from_id(&self.display_handle, id).ok())
    {
        resource.post_error(
            xdg_wm_base::Error::InvalidSurfaceState,
            "committed window geometry violates acknowledged fullscreen or maximized configure",
        );
    } else {
        self.display_handle
            .backend_handle()
            .kill_client(client.id(), DisconnectReason::ConnectionClosed);
    }
}

fn apply_initial_states(&mut self, id: WindowId) -> Result<(), flux_layout::LayoutError> {
    let requested = self
        .windows
        .get(id)
        .expect("admitted role")
        .initial_maximized;
    let max_result = match self.layout.set_maximized(id, requested) {
        Err(
            flux_layout::LayoutError::InvalidConstraints
            | flux_layout::LayoutError::InvalidGeometry,
        ) => {
            // Hints or viewport may change between the initial configure and
            // first buffer. Keep successful base admission and send normal
            // state rather than trapping the live client in a retry loop.
            self.windows
                .get_mut(id)
                .expect("admitted role")
                .initial_maximized = false;
            self.bump_sequence();
            self.layout.set_maximized(id, false)
        }
        result => result,
    };
    max_result?;
    let requested = self
        .windows
        .get(id)
        .expect("admitted role")
        .initial_fullscreen;
    match self.layout.set_fullscreen(id, requested) {
        Err(
            flux_layout::LayoutError::InvalidConstraints
            | flux_layout::LayoutError::InvalidGeometry,
        ) => {
            self.windows
                .get_mut(id)
                .expect("admitted role")
                .initial_fullscreen = false;
            self.bump_sequence();
            self.layout.set_fullscreen(id, false)
        }
        result => result,
    }
}

fn owns_click_grab(&self, id: WindowId) -> bool {
    use smithay::reexports::wayland_server::Resource;
    let Some(top) = self.windows.get(id).and_then(|item| item.window.toplevel()) else {
        return false;
    };
    let Some(pointer) = self.seat.get_pointer() else {
        return false;
    };
    pointer
        .with_grab(|_, grab| grab.is::<smithay::input::pointer::ClickGrab<Self>>())
        .unwrap_or(false)
        && pointer
            .grab_start_data()
            .and_then(|data| data.focus)
            .is_some_and(|(focus, _)| focus.id().same_client_as(&top.wl_surface().id()))
}

pub fn set_window_maximized(&mut self, id: WindowId, maximized: bool) -> Result<(), String> {
    if self.stopping || self.shutdown_deadline.is_some() {
        return Err("instance is shutting down".into());
    }
    let item = self
        .windows
        .get(id)
        .filter(|item| item.window.alive())
        .ok_or("unknown window")?;
    let current = if item.mapped {
        self.layout.is_maximized(id)
    } else {
        item.initial_maximized
    };
    if current == maximized {
        return Ok(());
    }
    if self.seat.get_keyboard().is_some_and(|k| k.is_grabbed())
        || (self.seat.get_pointer().is_some_and(|p| p.is_grabbed())
            && !self.owns_click_grab(id))
    {
        return Err("an input grab is active".into());
    }
    if item.mapped {
        self.layout
            .set_maximized(id, maximized)
            .map_err(|e| e.to_string())?;
        self.relayout();
    } else {
        let size =
            if maximized {
                self.layout
                    .maximize_size(self.constraints_for(
                        item.window.toplevel().expect("xdg role").wl_surface(),
                    ))
                    .map_err(|e| e.to_string())?
            } else {
                self.layout.viewport()
            };
        let item = self.windows.get_mut(id).expect("live role");
        item.initial_maximized = maximized;
        if let Some(top) = item.window.toplevel() {
            if item.initial_fullscreen {
                top.with_pending_state(|s|s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Maximized));
            } else {
                top.with_pending_state(|s| {
                s.size = maximized.then(|| (size.width.round() as i32, size.height.round() as i32).into());
                if maximized { s.states.set(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Maximized); }
                else { s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Maximized); }
            });
            }
        }
    }
    self.bump_sequence();
    Ok(())
}

pub fn set_window_fullscreen(&mut self, id: WindowId, fullscreen: bool) -> Result<(), String> {
    if self.stopping || self.shutdown_deadline.is_some() {
        return Err("instance is shutting down".into());
    }
    let item = self
        .windows
        .get(id)
        .filter(|i| i.window.alive())
        .ok_or("unknown window")?;
    let current = if item.mapped {
        self.layout.is_fullscreen(id)
    } else {
        item.initial_fullscreen
    };
    if current == fullscreen {
        return Ok(());
    }
    if self.seat.get_keyboard().is_some_and(|k| k.is_grabbed())
        || (self.seat.get_pointer().is_some_and(|p| p.is_grabbed())
            && !self.owns_click_grab(id))
    {
        return Err("an input grab is active".into());
    }
    if item.mapped {
        self.layout
            .set_fullscreen(id, fullscreen)
            .map_err(|e| e.to_string())?;
        self.relayout();
    } else {
        let top = item.window.toplevel().expect("xdg role").clone();
        let constraints = self.constraints_for(top.wl_surface());
        let size = if fullscreen {
            Some(
                self.layout
                    .fullscreen_size(constraints)
                    .map_err(|e| e.to_string())?,
            )
        } else if item.initial_maximized {
            self.layout.maximize_size(constraints).ok()
        } else {
            None
        };
        let item = self.windows.get_mut(id).expect("live role");
        item.initial_fullscreen = fullscreen;
        if !fullscreen && size.is_none() {
            item.initial_maximized = false;
        }
        let maximized = !fullscreen && item.initial_maximized;
        top.with_pending_state(|s| {
            s.size=size.map(|size|(size.width.round() as i32,size.height.round() as i32).into());
            if fullscreen { s.states.set(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Fullscreen); }
            else { s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Fullscreen); }
            if maximized { s.states.set(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Maximized); }
            else { s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Maximized); }
        });
    }
    self.bump_sequence();
    Ok(())
}

